const b = $input.first().json.body || $input.first().json;
const acres = Number(b.acres) || 1.2;
const ask = Number(b.ask) || Math.round(acres * 185000);
const maxUnits = Math.max(1, Math.floor(acres * 8));
const score = Math.round(54 + (maxUnits > 4 ? 18 : 8));
const rec = score >= 78 ? 'pursue' : score >= 62 ? 'watch' : 'pass';
return [{ json: { runId: b.runId, callbackUrl: b.callbackUrl, result: {
  title: b.query,
  subtitle: acres + ' acres · ' + maxUnits + ' units by-right (est.)',
  investorScore: score,
  recommendation: rec,
  summary: `At $${ask.toLocaleString()} this parcel pencils a pad if utilities are at the curb.`,
  metrics: [
    { label: 'Asking', value: '$' + ask.toLocaleString() },
    { label: 'Acres', value: String(acres) },
    { label: 'Est. max units', value: String(maxUnits) }
  ],
  sections: [{ heading: 'GIS', body: 'Replace this Code node with county parcel + FEMA flood lookups, then keep the callback payload shape.' }]
} } }];
